// Formatea importes al estándar español ("79,90 €") y fechas a "DD/MM/AAAA"
// Respetando los datos calculados por la app (Constitución I)
const item = $json;

const formateadorMoneda = new Intl.NumberFormat('es-ES', {
  style: 'currency',
  currency: 'EUR'
});

const precio_formateado = formateadorMoneda.format(item.precio || 0);
const abonado_formateado = formateadorMoneda.format(item.abonado || 0);
const pendiente_formateado = formateadorMoneda.format(item.pendiente || 0);

let fecha_limite_formateada = item.fecha_limite || '';
if (typeof fecha_limite_formateada === 'string' && fecha_limite_formateada.includes('-')) {
  const partes = fecha_limite_formateada.split('-');
  if (partes.length === 3) {
    fecha_limite_formateada = `${partes[2]}/${partes[1]}/${partes[0]}`;
  }
}

// Omite la talla si es nula o vacía sin mostrar 'null' (CA-2 y CA-3)
const detalle_producto = item.talla ? `${item.producto} (Talla ${item.talla})` : item.producto;

// Indica si está liquidado desde el alta
const es_liquidado = item.estado === 'liquidado';

return {
  ...item,
  precio_formateado,
  abonado_formateado,
  pendiente_formateado,
  fecha_limite_formateada,
  detalle_producto,
  es_liquidado
};
